package workflow
import("context";"errors";"strings";"testing";"time";"github.com/google/uuid";"photoeditor/backend/internal/delivery";"photoeditor/backend/internal/masknpy";"photoeditor/backend/internal/objectstore";"photoeditor/backend/internal/v2input")
func TestPhysicalDeliveryFailureBindsExactObjectAndKeepsTransientIO(t *testing.T){ref:=v2input.Ref{ArtifactID:uuid.New(),SHA256:strings.Repeat("a",64)};for _,value:=range []struct{cause error;code string}{{objectstore.ErrMissing,"SOURCE_OBJECT_MISSING"},{objectstore.ErrIntegrity,"SOURCE_OBJECT_INTEGRITY"},{masknpy.ErrInvalid,"SOURCE_NPY_INVALID"}}{err:=physicalDeliveryFailure(ref,"version-pinned",value.cause);var physical *deliveryPhysicalSourceFailure;if !errors.As(err,&physical)||physical.Ref!=ref||physical.Version!="version-pinned"||physical.Code!=value.code||!errors.Is(err,value.cause){t.Fatal(err)}};for _,cause:=range []error{context.DeadlineExceeded,context.Canceled,errors.New("temporary storage failure"),v2input.ErrInvalid}{err:=physicalDeliveryFailure(ref,"version-pinned",cause);var physical *deliveryPhysicalSourceFailure;if errors.As(err,&physical)||err!=cause{t.Fatal("transient/provenance error terminalized",err)}}}
type physicalDriverStore struct{*deliveryDriverStore;accepted bool;finalizeErr error;callsFinal int;cancelFinal context.CancelFunc;seen *deliveryPhysicalSourceFailure}
func(s *physicalDriverStore)FailPhysicalSource(_ context.Context,_ delivery.ExpansionLease,ref v2input.Ref,version,code string,slot int,request string,watermark bool)(bool,error){s.callsFinal++;s.seen=&deliveryPhysicalSourceFailure{Ref:ref,Version:version,Code:code,Slot:slot,Request:request,Watermark:watermark};if s.cancelFinal!=nil{s.cancelFinal()};return s.accepted,s.finalizeErr}
type physicalChild struct{err error}
func(p physicalChild)ProcessChild(context.Context,delivery.ExpansionLease,delivery.PreparePlan,delivery.ExportChildIntent)(DeliveryChildAdmission,error){return DeliveryChildAdmission{},p.err}
func TestDeliveryPhysicalFailureFinalizesOnlyUnderAcceptedCurrentLease(t *testing.T){plan,parent,_,_,_:=deliveryExportPlanFixture(t,nil);ref:=v2input.Ref{ArtifactID:uuid.New(),SHA256:strings.Repeat("a",64)}
 for _,scenario:=range []string{"accepted","stale","transient","finalizer_io"}{t.Run(scenario,func(t *testing.T){calls:=[]string{};store:=&physicalDriverStore{deliveryDriverStore:&deliveryDriverStore{calls:&calls,plan:plan,lease:&delivery.ExpansionLease{Expansion:uuid.New(),Token:uuid.New(),Tenant:uuid.New(),Run:parent,Workflow:uuid.New(),Package:uuid.New(),ParentTask:plan.TaskID(),Until:time.Now().Add(time.Minute),SlotCount:1}},accepted:scenario=="accepted"};err:=physicalDeliveryFailure(ref,"exact-version",objectstore.ErrMissing);bindDeliveryPhysicalFailure(&err,0,`{"frozen":"request"}`,false);if scenario=="transient"{err=errors.New("temporary io")};if scenario=="finalizer_io"{store.finalizeErr=errors.New("sql unavailable")};progress,got:=(DeliveryExpansionDriver{Store:store,Children:physicalChild{err},PageSize:1}).ProcessOne(context.Background());if scenario=="accepted"{if got!=nil||progress.AssemblyState!="finalized_failed"||progress.Admitted!=0||store.callsFinal!=1||store.seen.Ref!=ref||store.seen.Version!="exact-version"{t.Fatal(progress,got,store.seen)};for _,call:=range calls{if call=="release"{t.Fatal("released terminal fenced lease")}}}else{if got==nil||progress.AssemblyState=="finalized_failed"||progress.Admitted!=0{t.Fatal(progress,got)};if scenario=="transient"&&store.callsFinal!=0{t.Fatal("network failure reported as permanent")}}})}
}

func TestDeliveryPhysicalFailureLateCancellationRetainsDurableOutcomeWithoutSuccess(t *testing.T) {
 plan,parent,_,_,_:=deliveryExportPlanFixture(t,nil)
 calls:=[]string{}
 ctx,cancel:=context.WithCancel(context.Background());defer cancel()
 store:=&physicalDriverStore{deliveryDriverStore:&deliveryDriverStore{calls:&calls,plan:plan,lease:&delivery.ExpansionLease{Expansion:uuid.New(),Token:uuid.New(),Tenant:uuid.New(),Run:parent,Workflow:uuid.New(),Package:uuid.New(),ParentTask:plan.TaskID(),Until:time.Now().Add(time.Minute),SlotCount:1}},accepted:true,cancelFinal:cancel}
 failure:=physicalDeliveryFailure(v2input.Ref{ArtifactID:uuid.New(),SHA256:strings.Repeat("a",64)},"exact-version",objectstore.ErrMissing)
 bindDeliveryPhysicalFailure(&failure,0,`{"frozen":"request"}`,false)
 progress,err:=(DeliveryExpansionDriver{Store:store,Children:physicalChild{failure},PageSize:1}).ProcessOne(ctx)
 if !errors.Is(err,context.Canceled)||progress.AssemblyState=="finalized_failed"||store.callsFinal!=1{t.Fatal(progress,err,store.callsFinal)}
 for _,call:=range calls{if call=="release"{t.Fatal("cancelled invocation released durable terminal lease")}}
}
